#include <vector>
#include <set>
using namespace std;

class Solution {
public:
    int countDistinctSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        vector<long long> pref(n + 1, 0);
        for (int i = 0; i < n; ++i) {
            pref[i + 1] = pref[i] + nums[i];
        }
        set<vector<int>> distinct_subarrays;
        for (int i = 0; i < n; ++i) {
            for (int j = i; j < n; ++j) {
                if ((pref[j + 1] - pref[i]) % k == 0) {
                    distinct_subarrays.insert(vector<int>(nums.begin() + i, nums.begin() + j + 1));
                }
            }
        }
        return distinct_subarrays.size();
    }
};

import java.util.*;

class Solution {
    public int countDistinctSubarrays(int[] nums, int k) {
        int n = nums.length;
        long[] pref = new long[n + 1];
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i] + nums[i];
        }
        Set<List<Integer>> distinct = new HashSet<>();
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                if ((pref[j + 1] - pref[i]) % k == 0) {
                    List<Integer> sub = new ArrayList<>();
                    for (int idx = i; idx <= j; idx++) sub.add(nums[idx]);
                    distinct.add(sub);
                }
            }
        }
        return distinct.size();
    }
}

var countDistinctSubarrays = function(nums, k) {
    const n = nums.length;
    const pref = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) {
        pref[i + 1] = pref[i] + nums[i];
    }
    const distinct = new Set();
    for (let i = 0; i < n; i++) {
        for (let j = i; j < n; j++) {
            if ((pref[j + 1] - pref[i]) % k === 0) {
                distinct.add(nums.slice(i, j + 1).join(','));
            }
        }
    }
    return distinct.size;
};
